export const CODE: Record<string, string> = {
  "brain.py": "\"\"\"15-claude-harness brain - a claude-code-style agent (wiring, no loop).\n\nLayout\n------\n    config.py                 shared settings + the llm() factory (one Qwen\n                              2.5-Coder endpoint for all three roles)\n    neurons/model/            assistant, explorer, compactor  (stock LLM\n                              Neurons; behaviour via @before_task /\n                              @detects_output; chains declared as\n                              @AXON.host.on_agent_output)\n    effector/                 files, shell, websearch, fetch  (tools - real\n                              Effectors, TOOL_CALL/TOOL_RESULT serviced by\n                              the SDK the moment they're attached)\n    engram/session_memory.py  the ENGRAM; its persistence reaction is\n                              declared there as @ENGRAM.host.on_imprint_signal\n    brain.py                  wiring + loop-less run_turn / run_compact\n    demo.py                   the interactive REPL\n\nThere is NO agent loop anywhere - and since this example moved to\nEffectorBindings + tool_standard=\"hermes\", there is no tool protocol\nanywhere either. The assistant's Axon declares its bindings and the\ndialect its model natively speaks; per step the SDK parses the model's\n<tool_call> tag, resolves the binding, dispatches through the\nEffectorClient, and the observation rides the AGENT_OUTPUT into the chain\nhandler. ``run_turn`` dispatches ONE capability-routed TASK ([\"assistant\"])\nand waits for the trace's FINAL. Everything else is the Dendrites'\nresponsibility - they pick relevant Signals up and create more TASKs:\n\n    assistant-node @on_agent_output(neuron=\"assistant\") -> tool observation\n                   (the SDK already RAN the tool inside the TASK): imprint\n                   it, next [\"assistant\"] TASK step+1; the virtual \"agent\"\n                   tool (bound to no Effector on purpose) -> TASK\n                   [\"explorer\"]; an answer -> imprint the turn + emit FINAL\n                   (+ TASK [\"compactor\"] when the transcript is long)\n    explorer-node  @on_agent_output(neuron=\"explorer\")  -> TASK [\"assistant\"]\n    compactor-node @on_agent_output(neuron=\"compactor\") -> upsert summary,\n                   emit FINAL\n    engram host    @ENGRAM.host.on_imprint_signal (declared in\n                   engram/session_memory.py)           -> mirror \"summary\"\n                   imprints to workspace/SESSION.md\n\nChain state rides the TASK inputs; the transcript and tool observations\nare recalled from the engram, not held by any node. All chain TASKs share\nthe turn's trace so its FINAL resolves the caller's Pathway. Tool\ninvocations are NOT tasks: they ride TOOL_CALL -> TOOL_RESULT signal pairs\non the SAME trace (parent_id = the TASK), serviced natively by whichever\nDendrite has ``attach_effector``-ed the target Effector. Tool calls are\nNOT role-gated; the model nodes are role=\"orchestrator\" only because\ntheir chain handlers dispatch TASKs. Agents own their tools - as\nEffectorBindings on their Axons:\n\n    assistant -> files, shell, websearch, fetch (hermes <tool_call> -> SDK)\n    explorer  -> websearch-effector, fetch-effector (dendrite.call_tool)\n    engram host -> files-effector (dendrite.call_tool)\n\"\"\"\nfrom __future__ import annotations\n\nfrom cosmonapse import Dendrite, SignalType, new_trace_id\n\nfrom config import HEARTBEAT_S, MAX_STEPS, NAMESPACE\nfrom effector import fetch, files, shell, websearch\nfrom engram import session_memory\nfrom neurons.model import assistant, compactor, explorer\n\n# Agent Axons: hooks AND chain handlers are declared in their modules.\nAGENT_AXONS = [assistant.AXON, explorer.AXON, compactor.AXON]\n# Plain tools: worker nodes, they never dispatch. websearch + fetch share\n# ONE dendrite (two Effectors on web-node) - the Dendrite routes each\n# TOOL_CALL to the right Effector by directed.id/kind on its own, no\n# host-decorator filtering needed on this side anymore.\nWEB_EFFECTORS = [websearch.EFFECTOR, fetch.EFFECTOR]\nTOOL_EFFECTORS = [files.EFFECTOR, shell.EFFECTOR]\n\n\ndef build_harness(synapse):\n    \"\"\"Engram host + one Dendrite per Axon/Effector + the REPL's\n    orchestrator. The agents' chain handlers self-register on start\n    (@AXON.host.on_*), and so does the engram host's persistence reaction\n    (@ENGRAM.host.on_imprint_signal, declared in engram/session_memory.py).\n    Effectors need no such registration - attach_effector alone makes a\n    Dendrite service that tool's TOOL_CALLs.\n\n    Liveness is deliberately quiet: a single-process (or few-process)\n    harness does not need 30s beats, so ``heartbeat_s`` is a knob\n    (HARNESS_HEARTBEAT_S, default 300) and ``reregister_on_heartbeat=False``\n    keeps REGISTER a once-at-announce Signal instead of a periodic\n    re-broadcast - `cosmo prism --tail` shows the chain, not chatter. Only\n    Axon-hosting Dendrites beat at all; the shared kwargs are uniform\n    anyway.\"\"\"\n    liveness = {\"heartbeat_s\": HEARTBEAT_S, \"reregister_on_heartbeat\": False}\n    host = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=f\"{session_memory.ENGRAM_ID}-host\",\n                    role=\"worker\", **liveness)   # TOOL_CALLs aren't role-gated\n    host.attach_engram(session_memory.ENGRAM)  # @ENGRAM.host.on_* applied on start\n\n    dendrites = [host]\n    for axon in AGENT_AXONS:\n        node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                        dendrite_id=f\"{axon.neuron_id}-node\",\n                        role=\"orchestrator\", **liveness)\n        node.attach_axon(axon)             # @AXON.host.on_* applied on announce\n        dendrites.append(node)\n    web = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                   dendrite_id=\"web-node\", role=\"worker\", **liveness)\n    for effector in WEB_EFFECTORS:          # one node, two tool Effectors\n        web.attach_effector(effector)\n    dendrites.append(web)\n    for effector in TOOL_EFFECTORS:\n        node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                        dendrite_id=f\"{effector.effector_kind}-node\",\n                        role=\"worker\", **liveness)\n        node.attach_effector(effector)\n        dendrites.append(node)\n    repl = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"harness-repl\", role=\"orchestrator\",\n                    **liveness)\n    dendrites.append(repl)\n    return dendrites, repl\n\n\n# ---------------------------------------------------------------------------\n# run_turn / run_compact - dispatch ONE TASK, wait for FINAL. No loop.\n# ---------------------------------------------------------------------------\n\nasync def run_turn(repl, prompt: str, session: str, *,\n                   max_steps: int = MAX_STEPS,\n                   timeout_s: float = 600.0) -> dict:\n    tag = new_trace_id()        # the turn's trace; also tags its obs entries\n    await repl.imprint(         # the user's side of the transcript\n        engram_id=session_memory.ENGRAM_ID, op=\"append\",\n        entry={\"content\": f\"user: {prompt}\", \"tags\": [\"turn\", session]},\n        await_ack=True, deadline_ms=2000)\n    sig = await repl.dispatch_and_wait(\n        capabilities=[\"assistant\"],\n        input={\"prompt\": prompt, \"session\": session, \"tag\": tag,\n               \"step\": 1, \"max_steps\": max_steps, \"tools_used\": []},\n        trace_id=tag,\n        scope=\"terminal\",       # resolve on FINAL / ERROR only\n        finalize=False,         # the assistant node owns FINAL\n        timeout_s=timeout_s,\n    )\n    if sig.type is SignalType.ERROR:\n        raise RuntimeError(f\"turn failed: {sig.payload.get('message')}\")\n    return sig.payload[\"result\"]\n\n\nasync def run_compact(repl, session: str, *, timeout_s: float = 120.0) -> dict:\n    sig = await repl.dispatch_and_wait(\n        capabilities=[\"compactor\"], input={\"session\": session},\n        scope=\"terminal\", finalize=False, timeout_s=timeout_s,\n    )\n    if sig.type is SignalType.ERROR:\n        raise RuntimeError(f\"compact failed: {sig.payload.get('message')}\")\n    return sig.payload[\"result\"]\n",
  "demo.py": "\"\"\"Interactive REPL for the claude-code-style harness.\n\nSingle process: in-process MemorySynapse hosting the engram host, the model\nnodes, the tool nodes, and the REPL's orchestrator. Set SYNAPSE_URL to a\nrunning synapse to split across processes - and to watch the chain live:\n\n    cosmo prism --tail --url=$SYNAPSE_URL -n harness\n\nConfig comes from ../.env (cosmonapse-examples/.env) - it needs a real\nLLM_API_KEY (the bearer token for the Qwen2.5-Coder endpoint);\nLLM_ENDPOINT / LLM_MODEL / SYNAPSE_URL / HARNESS_* knobs are optional.\n\nRun:\n    python demo.py\n\n    ❯ read hello.py, then rewrite it with argparse and a --shout flag\n    ❯ /compact\n    ❯ /memory\n    ❯ /quit\n\nTool activity streams inline (⏺ lines) - the REPL's Dendrite simply\nsubscribes to the namespace's TOOL_CALL / TOOL_RESULT / AGENT_OUTPUT\nSignals; nothing extra crosses the wire.\n\"\"\"\nimport asyncio\nimport json\nimport os\nimport time\nfrom contextlib import AsyncExitStack\n\nfrom cosmonapse import MemorySynapse, connect_synapse\n\nfrom brain import build_harness, run_compact, run_turn\nfrom config import MAX_STEPS, WORKSPACE\nfrom engram import session_memory\n\nDIM, CYAN, BOLD, RESET = \"\\033[2m\", \"\\033[36m\", \"\\033[1m\", \"\\033[0m\"\n\nHELP = \"\"\"commands:\n  /help      this help\n  /memory    what the engram holds (turns / observations / summary)\n  /compact   compress the transcript into a session summary now\n  /quit      leave (also: /exit, ctrl-d)\nanything else is a request for the assistant.\"\"\"\n\n\ndef _memory_report():\n    entries = list(getattr(session_memory.ENGRAM, \"_entries\", {}).values())\n    kinds = [(e.tags or [\"?\"])[0] for e in entries]\n    return (f\"engram entries: {len(entries)}  \"\n            f\"(turns: {kinds.count('turn')}, obs: {kinds.count('obs')}, \"\n            f\"summaries: {kinds.count('summary')})\")\n\n\nasync def main():\n    url = os.environ.get(\"SYNAPSE_URL\")\n    if url:\n        synapse = await connect_synapse(url)\n    else:\n        synapse = MemorySynapse()\n        await synapse.connect()\n\n    WORKSPACE.mkdir(exist_ok=True)\n    dendrites, repl = build_harness(synapse)\n\n    @repl.on_tool_call\n    async def show_call(sig):\n        p = sig.payload\n        args = json.dumps(p.get(\"args\") or {})\n        print(f\"{DIM}  ⏺ {p.get('tool')} {args[:110]}{RESET}\")\n\n    @repl.on_tool_result\n    async def show_result(sig):\n        p = sig.payload\n        if p.get(\"error\"):\n            print(f\"{DIM}    ✗ {str(p['error'])[:110]}{RESET}\")\n\n    @repl.on_agent_output(neuron=\"assistant\")\n    async def show_step(sig):\n        out = sig.payload.get(\"output\", {})\n        if out.get(\"tool\") == \"agent\":\n            task = (out.get(\"args\") or {}).get(\"task\", \"\")\n            print(f\"{DIM}  ⏺ agent → explorer: {str(task)[:100]}{RESET}\")\n\n    session = f\"sess-{int(time.time())}\"\n    async with AsyncExitStack() as stack:\n        for d in dendrites:\n            await stack.enter_async_context(d)\n\n        print(f\"{BOLD}cosmonapse harness{RESET} - claude-code-style agent \"\n              f\"over Signals\\nworkspace: {WORKSPACE}  session: {session}\\n\"\n              f\"{DIM}{HELP}{RESET}\")\n        while True:\n            try:\n                line = (await asyncio.to_thread(input, f\"\\n{CYAN}❯{RESET} \"))\n            except (EOFError, KeyboardInterrupt):\n                break\n            line = line.strip()\n            if not line:\n                continue\n            if line in (\"/quit\", \"/exit\"):\n                break\n            if line == \"/help\":\n                print(HELP)\n                continue\n            if line == \"/memory\":\n                print(_memory_report())\n                continue\n            if line == \"/compact\":\n                try:\n                    out = await run_compact(repl, session)\n                    print(f\"compacted -> workspace/SESSION.md\\n{DIM}\"\n                          f\"{out['summary'][:400]}{RESET}\")\n                except (RuntimeError, asyncio.TimeoutError) as exc:\n                    print(f\"✗ {exc}\")\n                continue\n            try:\n                result = await run_turn(repl, line, session,\n                                        max_steps=MAX_STEPS)\n                used = \",\".join(result.get(\"tools_used\") or []) or \"none\"\n                print(f\"\\n{result['answer']}\\n{DIM}[{result.get('steps')} \"\n                      f\"step(s), tools: {used}]{RESET}\")\n            except asyncio.TimeoutError:\n                print(\"✗ turn timed out\")\n            except RuntimeError as exc:\n                print(f\"✗ {exc}\")\n    await synapse.close()\n\n\nif __name__ == \"__main__\":\n    asyncio.run(main())\n",
  "effector/_mcp.py": "\"\"\"_mcp - wrap a Neuron(source=\"mcp\", ...) as an Effector.\n\nOne shared adapter so files.py / websearch.py / fetch.py are each a single\nNeuron(...) call: TOOL_CALL/TOOL_RESULT servicing is a built-in SDK feature\n(Dendrite.attach_effector), so there is no @AXON.host.on_tool_call /\nhand-rolled bus.tool_reply left to write per tool.\n\n``shape`` is where \"cosmonapse does not build your tools\" bites in the\nright direction: the assistant's Axon speaks the model's tool names\n(read / write / edit / ls / glob - what the hermes <tool_call> carries),\nand the Effector owns the translation onto the wrapped MCP server's own\ntool names and argument shapes (read -> read_text_file, path sandboxing,\nedit -> edits[]). Unknown names pass straight through, so direct callers\n(dendrite.call_tool with the server's native names, e.g. the engram\nhost's ``write_file`` mirror) keep working. The underlying Neuron owns\nthe subprocess: it spawns lazily on first call, torn down in close().\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any, Callable\n\nfrom cosmonapse import Effector, Neuron, ToolOutcome\n\n#: (tool, args) -> (server_tool, server_args); raise for bad args.\nToolShaper = Callable[[str, dict[str, Any]], tuple[str, dict[str, Any]]]\n\n\nclass MCPEffector(Effector):\n    \"\"\"Proxies TOOL_CALL onto an underlying MCP-server Neuron, through an\n    optional ``shape`` translation (model-facing name -> server name).\"\"\"\n\n    def __init__(\n        self,\n        *,\n        effector_id: str,\n        effector_kind: str,\n        mcp: Neuron,\n        shape: ToolShaper | None = None,\n        capabilities: list[str] | None = None,\n    ) -> None:\n        self.effector_id = effector_id\n        self.effector_kind = effector_kind\n        # empty = proxy: serve whatever the server (or shaper) accepts\n        self.capabilities: list[str] = capabilities or []\n        self._mcp = mcp\n        self._shape = shape\n\n    async def connect(self) -> None:\n        pass   # the MCP Neuron spawns its subprocess lazily, on first call\n\n    async def close(self) -> None:\n        await self._mcp.aclose()\n\n    async def invoke(\n        self,\n        tool: str,\n        args: dict[str, Any],\n        *,\n        call_id: str | None = None,\n        deadline_ms: int | None = None,\n        trace_id: str | None = None,\n    ) -> ToolOutcome:\n        server_tool, server_args = tool, dict(args or {})\n        if self._shape is not None:\n            try:\n                server_tool, server_args = self._shape(tool, server_args)\n            except Exception as exc:  # noqa: BLE001 - bad args, not a fault\n                return ToolOutcome(tool=tool, call_id=call_id,\n                                   error=f\"{type(exc).__name__}: {exc}\")\n        out = await self._mcp({\"tool\": server_tool, \"arguments\": server_args}, [])\n        if out.get(\"is_error\"):\n            return ToolOutcome(\n                tool=tool, call_id=call_id,\n                error=str(out.get(\"response\") or f\"{tool} failed\"),\n            )\n        return ToolOutcome(tool=tool, call_id=call_id, result=out)\n",
  "effector/fetch.py": "\"\"\"fetch - mcp-server-fetch (uvx) as an Effector. Tool: fetch a URL ->\nmarkdown/text. The server's own tool is already called ``fetch``; the\nshaper just clamps max_length for model-issued calls.\"\"\"\nfrom typing import Any\n\nfrom cosmonapse import Neuron\n\nfrom effector._mcp import MCPEffector\n\n\ndef _shape(tool: str, a: dict[str, Any]) -> tuple[str, dict[str, Any]]:\n    if tool == \"fetch\":\n        return \"fetch\", {\"url\": str(a.get(\"url\", \"\")),\n                         \"max_length\": int(a.get(\"max_length\", 4000))}\n    return tool, a\n\n\nEFFECTOR = MCPEffector(\n    effector_id=\"fetch-effector\", effector_kind=\"fetch\",\n    mcp=Neuron(source=\"mcp\", server=\"fetch\"),\n    shape=_shape,\n)\n",
  "effector/files.py": "\"\"\"files - filesystem MCP server (npx) as an Effector, sandboxed to workspace/.\n\nThe assistant's hermes <tool_call>s carry the model-facing names\n(read / write / edit / ls / glob); ``_shape`` translates them onto the\nserver's own tools (read_text_file / write_file / edit_file /\nlist_directory / search_files) and pins every path inside workspace/.\nThe translation used to live in the assistant's TOOLS dict - it belongs\nhere: the Effector owns its tool surface, the Axon just routes\n(EffectorBinding(tools=...)). Server-native names still pass through for\ndirect callers (the engram host mirrors SESSION.md via ``write_file``).\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom cosmonapse import Neuron\n\nfrom config import WORKSPACE\nfrom effector._mcp import MCPEffector\n\n\ndef _safe_path(rel: Any) -> str:\n    \"\"\"Resolve a model-supplied path inside the workspace, or raise.\"\"\"\n    p = (WORKSPACE / str(rel or \"\")).resolve()\n    if not str(p).startswith(str(WORKSPACE.resolve())):\n        raise ValueError(f\"path escapes the workspace: {rel}\")\n    return str(p)\n\n\ndef _shape(tool: str, a: dict[str, Any]) -> tuple[str, dict[str, Any]]:\n    if tool == \"read\":\n        return \"read_text_file\", {\"path\": _safe_path(a.get(\"path\"))}\n    if tool == \"write\":\n        return \"write_file\", {\"path\": _safe_path(a.get(\"path\")),\n                              \"content\": str(a.get(\"content\", \"\"))}\n    if tool == \"edit\":\n        return \"edit_file\", {\"path\": _safe_path(a.get(\"path\")),\n                             \"edits\": [{\"oldText\": str(a.get(\"old\", \"\")),\n                                        \"newText\": str(a.get(\"new\", \"\"))}]}\n    if tool == \"ls\":\n        return \"list_directory\", {\"path\": _safe_path(a.get(\"path\", \".\"))}\n    if tool == \"glob\":\n        return \"search_files\", {\"path\": _safe_path(a.get(\"path\", \".\")),\n                                \"pattern\": str(a.get(\"pattern\", \"*\"))}\n    return tool, a          # server-native name: pass through\n\n\nEFFECTOR = MCPEffector(\n    effector_id=\"files-effector\", effector_kind=\"filesystem\",\n    mcp=Neuron(source=\"mcp\", server=\"filesystem\", args=[str(WORKSPACE)]),\n    shape=_shape,\n)\n",
  "effector/shell.py": "\"\"\"shell - a hand-rolled tool Effector (example-02 style neuron_fn, now an\nEffector.serve() hook): one @EFFECTOR.on_tool_call handler, zero protocol\nknowledge. There is no reference MCP server for a sandboxed shell, so this\nis written by hand. Commands run with cwd=workspace/, a timeout, and a\nsmall denylist - this is a guardrail, not a security boundary.\n\nAnswers to ``bash`` (the model-facing name the assistant's binding routes\nhere) and ``run`` (the old direct-caller name).\n\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\n\nfrom cosmonapse import Effector, ToolOutcome\n\nfrom config import SHELL_TIMEOUT, WORKSPACE\n\nDENY = (\"sudo\", \"shutdown\", \"reboot\", \"mkfs\", \"rm -rf /\", \":(){\", \"dd if=\")\n\nEFFECTOR = Effector.serve(effector_id=\"shell-effector\", effector_kind=\"shell\")\n\n\n@EFFECTOR.on_tool_call\nasync def run(tool: str, args: dict):\n    if tool not in (\"bash\", \"run\"):\n        return None   # unhandled -> \"unhandled tool\" error on TOOL_RESULT\n    cmd = str(args.get(\"command\", \"\")).strip()\n    if not cmd:\n        return ToolOutcome(tool=tool, error=\"no command given\")\n    if any(bad in cmd for bad in DENY):\n        return ToolOutcome(tool=tool, error=f\"command refused (denylist): {cmd}\")\n    try:\n        proc = await asyncio.create_subprocess_shell(\n            cmd, cwd=str(WORKSPACE),\n            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.STDOUT)\n        out, _ = await asyncio.wait_for(proc.communicate(), SHELL_TIMEOUT)\n    except asyncio.TimeoutError:\n        proc.kill()\n        return ToolOutcome(tool=tool, error=f\"timed out after {SHELL_TIMEOUT}s: {cmd}\")\n    text = (out or b\"\").decode(errors=\"replace\")\n    if proc.returncode != 0:\n        return ToolOutcome(tool=tool, error=text or f\"exit {proc.returncode}\")\n    return ToolOutcome(tool=tool, result={\"response\": text or \"(no output)\",\n                                          \"result\": {\"exit_code\": proc.returncode}})\n",
  "effector/websearch.py": "\"\"\"websearch - DuckDuckGo MCP server (uvx) as an Effector.\n\nModel-facing name: ``websearch`` (shaped onto the server's ``search`` with\na default max_results); ``search`` passes through for direct callers (the\nexplorer's gather hook).\n\"\"\"\nfrom typing import Any\n\nfrom cosmonapse import Neuron\n\nfrom effector._mcp import MCPEffector\n\n\ndef _shape(tool: str, a: dict[str, Any]) -> tuple[str, dict[str, Any]]:\n    if tool == \"websearch\":\n        return \"search\", {\"query\": str(a.get(\"query\", \"\")),\n                          \"max_results\": int(a.get(\"max_results\", 5))}\n    return tool, a\n\n\nEFFECTOR = MCPEffector(\n    effector_id=\"websearch-effector\", effector_kind=\"websearch\",\n    mcp=Neuron(source=\"mcp\", command=\"uvx\", args=[\"duckduckgo-mcp-server\"]),\n    shape=_shape,\n)\n",
  "engram/session_memory.py": "\"\"\"session-memory - the harness's working memory.\n\nNo access neuron and no wiring helper: recall/imprint ARE Dendrite behaviour\n(``dendrite.recall(engram_id=...)`` / ``dendrite.imprint(engram_id=...)``).\nEntry kinds, by tag:\n\n    turn     one conversation turn (\"user: ...\" / \"assistant: ...\")\n             also tagged with the session id\n    obs      one tool observation, tagged with the turn's trace id\n    summary  the compacted session summary (merge_key ``summary:<session>``)\n\nThe host's persistence reaction (mirroring \"summary\" imprints to\n``workspace/SESSION.md``) is declared right here as\n``@ENGRAM.host.on_imprint_signal`` - the memory-side twin of the agent\nAxons' ``@AXON.host.on_agent_output`` chain handlers (see\nneurons/model/*.py). It queues at import time and is replayed onto\nwhichever Dendrite calls ``host.attach_engram(ENGRAM)`` + ``start()``\n(brain.py) - no hand-wired ``@host.on_*`` on that Dendrite instance\nneeded. ``ENGRAM.dendrite`` (set by ``attach_engram``, the memory-side\nanalogue of ``AXON.dendrite``) is how the handler reaches the hosting\nDendrite to call a tool through - ``dendrite.call_tool(effector_id=...)``,\nthe direct Effector equivalent of ``dendrite.recall``/``dendrite.imprint``.\n\"\"\"\nfrom cosmonapse import InMemoryEngram\n\nfrom config import WORKSPACE\n\nENGRAM_ID = \"session-memory\"\n\nENGRAM = InMemoryEngram(engram_id=ENGRAM_ID, engram_kind=\"context\")\n\n\n@ENGRAM.host.on_imprint_signal\nasync def persist_summaries(sig):\n    \"\"\"Mirror \"summary\" imprints carrying a path to disk (filesystem).\"\"\"\n    entry = sig.payload.get(\"entry\") or {}\n    path = (sig.meta or {}).get(\"path\")\n    if path and \"summary\" in (entry.get(\"tags\") or []):\n        outcome = await ENGRAM.dendrite.call_tool(\n            effector_id=\"files-effector\", tool=\"write_file\",\n            args={\"path\": str(WORKSPACE / path),\n                  \"content\": entry.get(\"content\", \"\")})\n        if outcome.error:\n            raise RuntimeError(f\"SESSION.md mirror failed: {outcome.error}\")\n",
  "neurons/model/assistant.py": "\"\"\"assistant - a STOCK LLM Neuron speaking its NATIVE tool dialect.\n\nQwen2.5-Coder is hermes-trained: it emits ``<tool_call>{\"name\", \"arguments\"}\n</tool_call>`` tags. The Axon declares that (``tool_standard=\"hermes\"``) plus\nthe EffectorBindings, and the SDK does the rest per step: parse the tag,\nresolve the binding (EffectorBinding.tools), dispatch through the\nEffectorClient, and hand the observation back on AGENT_OUTPUT\n({\"tool\", \"args\", \"result\"|\"error\", \"effector_id\"}). The hand-rolled action\nprotocol this example used to carry - the TOOLS dict, the JSON parser, the\n``pending`` field riding TASKs, the @before_task tool runner - is gone; the\nmodel never learns Cosmonapse exists.\n\n    Axon(effectors=[...], tool_standard=\"hermes\")   THE GATE: bindings\n                           require the dialect, so misconfiguration fails\n                           at construction\n\n    @AXON.before_task      recall the session summary + transcript + this\n                           turn's observations (dendrite.recall), build the\n                           prompt; stash the chain state per trace\n    @AXON.detects_output   only reached when the reply carries NO parseable\n                           tool call (a native match short-circuits\n                           recognisers): plain text IS the final answer;\n                           text that merely LOOKS like a call (a dropped\n                           </tool_call>, or an unescaped quote inside the\n                           object) is flagged \"malformed\"\n\n    @AXON.host.on_agent_output(neuron=\"assistant\")   THE CHAIN - routing\n    ONLY: a tool observation (the SDK already RAN the tool) -> imprint it,\n    next [\"assistant\"] TASK step+1; the virtual \"agent\" tool -> [\"explorer\"]\n    TASK; a \"malformed\" call attempt -> imprint the parse failure as an\n    observation and re-step (harness-level stand-in for the SDK's planned\n    InvalidOutput repair loop); an answer -> imprint the turn, kick\n    compaction when the transcript is long, emit FINAL (deferred host\n    decorator).\n\nChain state ({\"prompt\",\"session\",\"tag\",\"step\",\"max_steps\",\"tools_used\"})\nrides the TASK inputs; tool-call AGENT_OUTPUTs can't echo it (their payload\nis the SDK's observation shape), so the node bridges hook -> chain handler\nwith a per-trace module dict, the house pattern. Tool observations are\n*recalled from the engram*, not carried by any node.\n\n\"agent\" is deliberately bound to no Effector: the parsed call passes\nthrough with a no-binding note and the chain handler routes it as a nested\ncapability TASK to the explorer - the claude-code Task-tool analogue.\n\"\"\"\nimport datetime\nimport json\nimport os\nimport re\n\nfrom cosmonapse import Axon, EffectorBinding\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import COMPACT_AFTER, SHELL_TIMEOUT, llm, render\nfrom engram.session_memory import ENGRAM_ID\n\nMODEL = os.environ.get(\"HARNESS_ASSISTANT_MODEL\")   # None -> config.LLM_MODEL\n\n\ndef _schema(name, desc, props, required):\n    return json.dumps({\"type\": \"function\", \"function\": {\n        \"name\": name, \"description\": desc,\n        \"parameters\": {\"type\": \"object\", \"properties\": props,\n                       \"required\": required}}})\n\n\n_S = {\"type\": \"string\"}\nTOOL_SCHEMAS = \"\\n\".join([\n    _schema(\"read\", \"Read a file.\",\n            {\"path\": {**_S, \"description\": \"path relative to the workspace root\"}},\n            [\"path\"]),\n    _schema(\"write\", \"Create or overwrite a file.\",\n            {\"path\": _S, \"content\": _S}, [\"path\", \"content\"]),\n    _schema(\"edit\", \"Replace old text with new text in a file.\",\n            {\"path\": _S, \"old\": _S, \"new\": _S}, [\"path\", \"old\", \"new\"]),\n    _schema(\"ls\", \"List a directory ('.' = workspace root).\",\n            {\"path\": _S}, []),\n    _schema(\"glob\", \"Find files by name pattern.\",\n            {\"pattern\": _S, \"path\": _S}, [\"pattern\"]),\n    _schema(\"bash\", \"Run a shell command in the workspace.\",\n            {\"command\": _S}, [\"command\"]),\n    _schema(\"websearch\", \"Search the web.\", {\"query\": _S}, [\"query\"]),\n    _schema(\"fetch\", \"Read a web page.\", {\"url\": _S}, [\"url\"]),\n    _schema(\"agent\", \"Delegate focused web research to a subagent.\",\n            {\"task\": _S}, [\"task\"]),\n])\n\nSYSTEM = (\n    \"You are a coding assistant working in a sandboxed workspace directory. \"\n    \"You act in steps.\\n\\n\"\n    # Language pin: the served \"qwen\" alias has drifted into Thai on plain\n    # English requests (tool-calling intact, so the ChatML frame is fine -\n    # it is the weights). Harmless on a stock model, decisive on a\n    # localised finetune.\n    \"Always reply in English, whatever language the request is in.\\n\"\n    # Without a date the model treats its training cutoff as \"now\" and\n    # silently rewrites future years in tool queries to a year it knows -\n    # asked about the 2026 World Cup it searched for 2022 instead.\n    f\"Today's date is {datetime.date.today():%Y-%m-%d}. Your training data \"\n    \"is older than that: for anything that may have changed since, search \"\n    \"instead of answering from memory, and NEVER rewrite a date the user \"\n    \"gave you into an earlier one.\\n\\n\"\n    \"# Tools\\n\\n\"\n    \"You may call functions to assist with the user query. You are provided \"\n    \"with function signatures within <tools></tools> XML tags:\\n\"\n    f\"<tools>\\n{TOOL_SCHEMAS}\\n</tools>\\n\\n\"\n    \"To take an action, return exactly ONE json object with function name \"\n    \"and arguments within <tool_call></tool_call> XML tags:\\n\"\n    \"<tool_call>\\n\"\n    '{\"name\": <function-name>, \"arguments\": <args-json-object>}\\n'\n    \"</tool_call>\\n\\n\"\n    # NB: describe the tags in WORDS here, never by writing them out.\n    # <tool_call>/</tool_call> are added-vocab SPECIAL tokens in\n    # Qwen2.5; emitting them mid-sentence is off-distribution and an\n    # earlier draft of these lines (which did) coincided exactly with\n    # the model switching its replies to Thai. Keep them to the two\n    # canonical spots below - the \"within ... XML tags\" preamble and\n    # the example block - as Qwen's own template does.\n    \"Emit the tags and the object and NOTHING else - no prose before or \"\n    \"after, no explanation of what you are about to do.\\n\"\n    \"Always emit BOTH the opening and the closing tag; an unclosed \"\n    \"call is discarded.\\n\"\n    \"Never describe, simulate, or predict a tool's output - emit the call \"\n    \"and STOP. The real result arrives in the next step.\\n\"\n    \"Inside JSON string values escape every double quote as \\\\\\\" and every \"\n    \"newline as \\\\n - ONE unescaped quote makes the whole call \"\n    \"unparseable.\\n\\n\"\n    \"When the request is satisfied, reply with the final answer as plain \"\n    \"markdown text and NO <tool_call> tag.\\n\\n\"\n    \"Rules: one tool call per step; paths are relative to the workspace \"\n    \"root; read files before editing them; never invent file contents; if \"\n    \"a tool errors, adapt and try another way; answer as soon as the \"\n    \"request is satisfied - do not burn steps.\"\n)\n\n_CHAIN_KEYS = (\"prompt\", \"session\", \"tag\", \"step\", \"max_steps\", \"tools_used\")\n_OBS_LIMIT = 3000                   # chars of tool output fed back per step\n_STATE: dict[str, dict] = {}        # per-trace chain state: hook -> chain\n\nAXON = Axon(\n    neuron_id=\"assistant\", neuron_fn=llm(MODEL), capabilities=[\"assistant\"],\n    tool_standard=\"hermes\",         # Qwen's mother tongue - THE GATE\n    effectors=[\n        EffectorBinding(name=\"files\", directed_id=\"files-effector\",\n                        tools=(\"read\", \"write\", \"edit\", \"ls\", \"glob\")),\n        EffectorBinding(name=\"shell\", directed_id=\"shell-effector\",\n                        tools=(\"bash\",),\n                        default_deadline_ms=int(SHELL_TIMEOUT * 1000) + 5000),\n        EffectorBinding(name=\"websearch\", directed_id=\"websearch-effector\",\n                        tools=(\"websearch\",)),\n        EffectorBinding(name=\"fetch\", directed_id=\"fetch-effector\",\n                        tools=(\"fetch\",)),\n        # no binding for \"agent\" - see the module docstring\n    ],\n)\n\n\n@AXON.before_task\nasync def situate(input):\n    \"\"\"Recall summary + transcript + this turn's observations, then build\n    the prompt. No tool runs here anymore - the SDK dispatches natives.\"\"\"\n    tid, _ = ambient_trace()\n    d = AXON.dendrite\n    session, tag = input[\"session\"], input[\"tag\"]\n\n    summary = await d.recall(engram_id=ENGRAM_ID,\n                             query={\"merge_key\": f\"summary:{session}\"},\n                             deadline_ms=2000)\n    compacted = summary.hits[0].entry[\"content\"] if summary.hits else \"(none)\"\n\n    past = await d.recall(engram_id=ENGRAM_ID,\n                          query={\"tag\": session, \"top_k\": 50},\n                          deadline_ms=2000)\n    turns = [h.entry[\"content\"] for h in past.hits\n             if \"turn\" in h.entry.get(\"tags\", [])][-12:]\n\n    seen = await d.recall(engram_id=ENGRAM_ID,\n                          query={\"tag\": tag, \"top_k\": 50}, deadline_ms=2000)\n    obs = [h.entry[\"content\"] for h in seen.hits\n           if \"obs\" in h.entry.get(\"tags\", [])]\n\n    _STATE[tid] = {k: input.get(k) for k in _CHAIN_KEYS}\n\n    # Session context and the step budget belong in the system turn - they\n    # are standing instructions, not something anyone said.\n    system = SYSTEM\n    if compacted != \"(none)\":\n        system += f\"\\n\\n# Session summary\\n\\n{compacted}\"\n    system += f\"\\n\\nStep {input['step']}/{input['max_steps']}.\"\n\n    msgs = [{\"role\": \"system\", \"content\": system}]\n\n    # Prior transcript as REAL turns. run_turn imprints the user's message\n    # before dispatching, so the current request is already the last entry -\n    # drop it and re-add it below so it lands after the replayed history.\n    tail = f\"user: {input['prompt']}\"\n    if turns and turns[-1] == tail:\n        turns = turns[:-1]\n    for t in turns:\n        if t.startswith(\"assistant: \"):\n            msgs.append({\"role\": \"assistant\", \"content\": t[11:]})\n        else:\n            msgs.append({\"role\": \"user\",\n                         \"content\": t[6:] if t.startswith(\"user: \") else t})\n\n    msgs.append({\"role\": \"user\", \"content\": input[\"prompt\"]})\n\n    # This turn's tool history, in the shape Qwen was trained on: the call\n    # as an assistant turn, the result as a <tool_response> user turn.\n    for raw in obs:\n        try:\n            rec = json.loads(raw)\n        except (ValueError, TypeError):\n            rec = {\"note\": raw}\n        if \"tool\" in rec:\n            call = json.dumps({\"name\": rec[\"tool\"],\n                               \"arguments\": rec.get(\"args\") or {}})\n            msgs.append({\"role\": \"assistant\",\n                         \"content\": f\"<tool_call>\\n{call}\\n</tool_call>\"})\n            msgs.append({\"role\": \"user\",\n                         \"content\": \"<tool_response>\\n\"\n                                    f\"{rec.get('body', '')}\\n</tool_response>\"})\n        else:\n            msgs.append({\"role\": \"user\", \"content\": rec.get(\"note\", str(raw))})\n\n    return {\"prompt\": render(msgs)}\n\n\n#: A bare call object - the two keys in order, opening the object. Tight\n#: on purpose: prose *about* tool calls must not trip it, only a literal\n#: {\"name\": \"...\", \"arguments\": ... } does.\n_BARE_CALL = re.compile(r'\\{\\s*\"name\"\\s*:\\s*\"[^\"]+\"\\s*,\\s*\"arguments\"\\s*:')\n\n\ndef _mask(text: str) -> str:\n    \"\"\"Neutralise tool_call tags before quoting a bad reply BACK to the\n    model. It still needs to see what it emitted, but the tags are\n    added-vocab special tokens and feeding them back inside prose is the\n    off-distribution pattern that coincided with this model dropping into\n    another language. The placeholders keep the diagnostic legible.\"\"\"\n    return (text.replace(\"</tool_call>\", \"(closing tool_call tag)\")\n                .replace(\"<tool_call>\", \"(opening tool_call tag)\"))\n\n\ndef _looks_like_call(text: str) -> bool:\n    \"\"\"A reply the hermes parser refused but that clearly TRIED to be a\n    call. parse_hermes needs BOTH tags around valid JSON, and this\n    endpoint drops or CORRUPTS either one - observed live: `ичество` in\n    place of </tool_call>, and `forCell` in place of <tool_call>. So\n    EITHER tag alone is enough of a tell, and if token corruption eats\n    both, the bare object still is. Without this the model emits a\n    perfectly good call and the turn ends at step 1 as an \"answer\".\"\"\"\n    return (\"<tool_call>\" in text or \"</tool_call>\" in text\n            or bool(_BARE_CALL.search(text)))\n\n\n@AXON.detects_output\ndef decide(raw):\n    \"\"\"Only reached when the reply held no PARSEABLE <tool_call> (a native\n    match short-circuits recognisers): plain text IS the answer; text that\n    merely looks like a call is flagged for the chain to retry. Echo the\n    chain.\"\"\"\n    tid, _ = ambient_trace()\n    chain = _STATE.get(tid) or {}\n    text = (raw.get(\"response\") or \"\").strip()\n    if _looks_like_call(text):\n        return {\"malformed\": text, **chain}\n    return {\"answer\": text or \"(empty reply)\", **chain}\n\n\nasync def _conclude(node, sig, st, answer):\n    \"\"\"Remember the turn, maybe kick compaction, FINAL.\"\"\"\n    session = st.get(\"session\")\n    await node.imprint(\n        engram_id=ENGRAM_ID, op=\"append\",\n        entry={\"content\": f\"assistant: {answer}\", \"tags\": [\"turn\", session]},\n        await_ack=True, deadline_ms=2000,\n        trace_id=sig.trace_id, parent_id=sig.id)\n    past = await node.recall(engram_id=ENGRAM_ID,\n                             query={\"tag\": session, \"top_k\": 100},\n                             deadline_ms=2000,\n                             trace_id=sig.trace_id, parent_id=sig.id)\n    n_turns = sum(1 for h in past.hits if \"turn\" in h.entry.get(\"tags\", []))\n    if n_turns > COMPACT_AFTER:         # fire-and-forget /compact analogue\n        await node.dispatch_task(capabilities=[\"compactor\"],\n                                 input={\"session\": session})\n    _STATE.pop(sig.trace_id, None)\n    await node.emit_final(\n        trace_id=sig.trace_id, parent_id=sig.id, neuron=\"assistant\",\n        result={\"answer\": answer, \"tools_used\": st.get(\"tools_used\") or [],\n                \"steps\": st.get(\"step\", 1), \"trace_id\": st.get(\"tag\")})\n\n\n@AXON.host.on_agent_output(neuron=\"assistant\")\nasync def chain(sig):\n    \"\"\"The assistant node's chain behaviour - ROUTING ONLY. The SDK already\n    ran any native tool; this handler imprints the observation and creates\n    the next TASK, delegates to the explorer, or concludes the trace.\"\"\"\n    node = AXON.dendrite\n    out = sig.payload.get(\"output\", {})\n    st = dict(_STATE.get(sig.trace_id) or {})\n    step = st.get(\"step\") or 1\n\n    # A call attempt the parser refused (missing </tool_call>, invalid\n    # JSON) -> feed the parse failure back as an observation and give the\n    # model the step again. Harness-level stand-in for the SDK's planned\n    # InvalidOutput + output_retries repair loop; the step budget still\n    # bounds the trace.\n    if \"malformed\" in out:\n        st = {**st, **{k: out[k] for k in _CHAIN_KEYS\n                       if out.get(k) is not None}}\n        step = st.get(\"step\") or 1\n        obs = json.dumps({\"note\":\n            \"[invalid tool call]\\nYour previous reply looked like a tool \"\n            \"call but could NOT be parsed - a missing or corrupted opening \"\n            \"or closing tool_call tag, or an unescaped double quote or raw \"\n            \"newline inside a JSON string value. Re-emit ONE complete call: \"\n            \"the opening tag, the object on its own line, the closing tag, \"\n            \"and nothing else. Escape every inner double quote and newline. \"\n            \"It was:\\n\" + _mask(str(out[\"malformed\"])[:600])})\n        await node.imprint(engram_id=ENGRAM_ID, op=\"append\",\n                           entry={\"content\": obs,\n                                  \"tags\": [\"obs\", st.get(\"tag\")]},\n                           await_ack=True, deadline_ms=2000,\n                           trace_id=sig.trace_id, parent_id=sig.id)\n        if step >= (st.get(\"max_steps\") or 0):\n            await _conclude(node, sig, st,\n                            \"I ran out of steps before finishing. Progress \"\n                            \"so far is in the workspace; ask me to \"\n                            \"continue.\")\n            return\n        await node.dispatch_task(\n            capabilities=[\"assistant\"],\n            input={**{k: st.get(k) for k in\n                      (\"prompt\", \"session\", \"tag\", \"max_steps\",\n                       \"tools_used\")},\n                   \"step\": step + 1},\n            trace_id=sig.trace_id, parent_id=sig.id)\n        return\n\n    # answer (no tool call in the reply) -> conclude.\n    if \"answer\" in out:\n        await _conclude(node, sig, {**st, **{k: out[k] for k in _CHAIN_KEYS\n                                             if out.get(k) is not None}},\n                        str(out[\"answer\"]))\n        return\n\n    if \"tool\" not in out:\n        return                          # not this chain's shape\n\n    tool, args = out[\"tool\"], out.get(\"args\") or {}\n    used = list(st.get(\"tools_used\") or []) + [tool]\n\n    # \"agent\" -> the claude-code Task tool: a nested capability TASK. It is\n    # bound to no Effector on purpose, so the SDK passed the call through\n    # (with a no-binding note we deliberately ignore) instead of running it.\n    if tool == \"agent\":\n        await node.dispatch_task(\n            capabilities=[\"explorer\"],\n            input={\"task\": str(args.get(\"task\", \"\")),\n                   **{k: st.get(k) for k in\n                      (\"prompt\", \"session\", \"tag\", \"step\", \"max_steps\")},\n                   \"tools_used\": used},\n            trace_id=sig.trace_id, parent_id=sig.id)\n        return\n\n    # A real tool ran (or failed) inside the assistant's TASK - the\n    # observation rides this very Signal. Imprint it for the next step's\n    # recall; errors go to the model too, it is expected to adapt.\n    if out.get(\"error\") is not None:\n        body = f\"ERROR: {out['error']}\"\n    else:\n        result = out.get(\"result\")\n        if isinstance(result, dict):\n            body = str(result.get(\"response\") or result.get(\"result\") or \"(ok)\")\n        else:\n            body = str(result if result is not None else \"(ok)\")\n    # Structured, NOT prose: situate() replays this as a real tool turn.\n    # The old f\"[{tool} {args}]\" form showed the model a call rendered as\n    # `fetch {\"url\": ...}` and it began emitting exactly that instead of\n    # the tagged form - the transcript teaching the wrong dialect.\n    obs = json.dumps({\"tool\": tool, \"args\": args,\n                      \"body\": body[:_OBS_LIMIT]})\n    await node.imprint(engram_id=ENGRAM_ID, op=\"append\",\n                       entry={\"content\": obs, \"tags\": [\"obs\", st.get(\"tag\")]},\n                       await_ack=True, deadline_ms=2000,\n                       trace_id=sig.trace_id, parent_id=sig.id)\n\n    # step budget: the next step would overshoot -> force a wrap-up.\n    if step >= (st.get(\"max_steps\") or 0):\n        await _conclude(node, sig, {**st, \"tools_used\": used},\n                        \"I ran out of steps before finishing. Progress so \"\n                        \"far is in the workspace; ask me to continue.\")\n        return\n\n    await node.dispatch_task(\n        capabilities=[\"assistant\"],\n        input={**{k: st.get(k) for k in\n                  (\"prompt\", \"session\", \"tag\", \"max_steps\")},\n               \"step\": step + 1, \"tools_used\": used},\n        trace_id=sig.trace_id, parent_id=sig.id)\n",
  "neurons/model/compactor.py": "\"\"\"compactor - a STOCK LLM Neuron; the harness's /compact analogue.\n\n    @AXON.before_task      recall the full session transcript\n    @AXON.detects_output   strip the summary, echo the session\n\n    @AXON.host.on_agent_output(neuron=\"compactor\")   THE CHAIN: upsert the\n    summary (merge_key ``summary:<session>``, meta.path -> the host mirrors\n    it to workspace/SESSION.md) and emit FINAL (deferred host decorator).\n\nReached two ways: the ``/compact`` REPL command (dispatch_and_wait) and\nfire-and-forget from the assistant's chain once the transcript passes\nCOMPACT_AFTER turns. The assistant's before_task always prepends the latest\nsummary, so compacted context survives even though old turns scroll away.\n\"\"\"\nimport os\n\nfrom cosmonapse import Axon\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import chatml, llm\nfrom engram.session_memory import ENGRAM_ID\n\nMODEL = os.environ.get(\"HARNESS_COMPACTOR_MODEL\")   # None -> config.LLM_MODEL\n\nSYSTEM = (\n    \"Compress this coding-session transcript into a dense summary for the \"\n    \"assistant's future context. Preserve: user goals, decisions made, files \"\n    \"created/edited (with paths), key facts learned, and open TODOs. \"\n    \"Plain text, no preamble.\"\n)\n\n_PENDING: dict[str, dict] = {}      # per-trace state: before_task -> detector\n\nAXON = Axon(neuron_id=\"compactor\", neuron_fn=llm(MODEL),\n            capabilities=[\"compactor\"])\n\n\n@AXON.before_task\nasync def collect(input):\n    \"\"\"Recall every turn of the session (dendrite.recall), then prompt.\"\"\"\n    tid, _ = ambient_trace()\n    past = await AXON.dendrite.recall(\n        engram_id=ENGRAM_ID,\n        query={\"tag\": input[\"session\"], \"top_k\": 200}, deadline_ms=2000)\n    turns = [h.entry[\"content\"] for h in past.hits\n             if \"turn\" in h.entry.get(\"tags\", [])]\n    _PENDING[tid] = dict(input)\n    return {\"prompt\": chatml(SYSTEM, \"\\n\".join(turns) or \"(empty session)\")}\n\n\n@AXON.detects_output\ndef summarize(raw):\n    tid, _ = ambient_trace()\n    st = _PENDING.pop(tid, {})\n    return {\"summary\": (raw.get(\"response\") or \"\").strip(),\n            \"session\": st.get(\"session\")}\n\n\n@AXON.host.on_agent_output(neuron=\"compactor\")\nasync def chain(sig):\n    \"\"\"Upsert the summary (the host mirrors it to disk) and conclude.\"\"\"\n    node = AXON.dendrite\n    out = sig.payload.get(\"output\", {})\n    session, summary = out.get(\"session\"), out.get(\"summary\", \"\")\n    await node.imprint(\n        engram_id=ENGRAM_ID, op=\"upsert\",\n        merge_key=f\"summary:{session}\",\n        entry={\"content\": summary, \"tags\": [\"summary\", session]},\n        meta={\"path\": \"SESSION.md\"},\n        await_ack=True, deadline_ms=2000,\n        trace_id=sig.trace_id, parent_id=sig.id)\n    await node.emit_final(\n        trace_id=sig.trace_id, parent_id=sig.id, neuron=\"compactor\",\n        result={\"summary\": summary, \"session\": session})\n",
  "neurons/model/explorer.py": "\"\"\"explorer - a STOCK LLM Neuron; the harness's Task-tool subagent.\n\n    @AXON.before_task      gather web context (websearch + fetch MCPs)\n    @AXON.detects_output   strip the findings, IMPRINT them as this turn's\n                           observation, echo the chain state\n\n    @AXON.host.on_agent_output(neuron=\"explorer\")   THE CHAIN: hands back\n    to the assistant with step + 1 (deferred host decorator).\n\nThe assistant delegates with {\"tool\": \"agent\", \"task\": ...}; the findings\ncome back as an ``obs`` engram entry the assistant recalls on its next step\n- the subagent's context never bloats the main transcript.\n\"\"\"\nimport os\nimport re\n\nimport json\n\nfrom cosmonapse import Axon\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import chatml, llm\nfrom engram.session_memory import ENGRAM_ID\n\nMODEL = os.environ.get(\"HARNESS_EXPLORER_MODEL\")   # None -> config.LLM_MODEL\n\nSYSTEM = (\n    \"You are a research subagent. Using ONLY the supplied web context, \"\n    \"report tight, factual findings that answer the task: key facts, \"\n    \"constraints, and concrete API/usage details. Cite URLs only if they \"\n    \"appear in the context. Do not invent facts.\"\n)\n\n_URL = re.compile(r\"https?://[^\\s)\\]]+\")\n_PENDING: dict[str, dict] = {}      # per-trace state: before_task -> detector\n\n\ndef _first_url(text):\n    m = _URL.search(text or \"\")\n    return m.group(0).rstrip(\".,);]\") if m else None\n\n\nAXON = Axon(neuron_id=\"explorer\", neuron_fn=llm(MODEL),\n            capabilities=[\"explorer\"])\n\n\n@AXON.before_task\nasync def gather(input):\n    \"\"\"Gather web context via MY tools, shaped into the prompt.\"\"\"\n    tid, _ = ambient_trace()\n    d = AXON.dendrite\n    task = input[\"task\"]\n\n    search_outcome = await d.call_tool(\n        effector_id=\"websearch-effector\", tool=\"search\",\n        args={\"query\": task, \"max_results\": 5})\n    if search_outcome.error:\n        raise RuntimeError(search_outcome.error)\n    search = search_outcome.result or {}\n    ctx = search.get(\"response\", \"\")[:1500]\n    url = _first_url(search.get(\"response\"))\n    if url:\n        page_outcome = await d.call_tool(\n            effector_id=\"fetch-effector\", tool=\"fetch\",\n            args={\"url\": url, \"max_length\": 2500})\n        if page_outcome.error:\n            raise RuntimeError(page_outcome.error)\n        page = page_outcome.result or {}\n        ctx += f\"\\n\\n[page {url}]\\n{page.get('response', '')[:2000]}\"\n\n    _PENDING[tid] = dict(input)\n    return {\"prompt\": chatml(SYSTEM, f\"Task: {task}\\n\\nWeb context:\\n{ctx}\")}\n\n\n@AXON.detects_output\nasync def report(raw):\n    \"\"\"Imprint the findings as this turn's observation, echo the chain.\"\"\"\n    tid, _ = ambient_trace()\n    st = _PENDING.pop(tid, {})\n    findings = (raw.get(\"response\") or \"\").strip()\n    await AXON.dendrite.imprint(\n        engram_id=ENGRAM_ID, op=\"append\",\n        entry={\"content\": json.dumps(\n                   {\"tool\": \"agent\",\n                    \"args\": {\"task\": st.get(\"task\", \"\")},\n                    \"body\": findings}),\n               \"tags\": [\"obs\", st.get(\"tag\", \"\")]},\n        await_ack=True, deadline_ms=2000,\n    )\n    return {\"findings\": findings,\n            **{k: st.get(k) for k in\n               (\"prompt\", \"session\", \"tag\", \"step\", \"max_steps\",\n                \"tools_used\")}}\n\n\n@AXON.host.on_agent_output(neuron=\"explorer\")\nasync def chain(sig):\n    \"\"\"The explorer node's chain behaviour - hand back to the assistant.\"\"\"\n    out = sig.payload.get(\"output\", {})\n    await AXON.dendrite.dispatch_task(\n        capabilities=[\"assistant\"],\n        input={**{k: out.get(k) for k in\n                  (\"prompt\", \"session\", \"tag\", \"max_steps\", \"tools_used\")},\n               \"step\": (out.get(\"step\") or 0) + 1},\n        trace_id=sig.trace_id, parent_id=sig.id,\n    )\n"
};
